import{_ as a,C as r,o as s,c as l,j as e,a as o,E as c,a6 as n}from"./chunks/framework.D9iQZIpB.js";const S=JSON.parse('{"title":"来源说明","description":"逐条可核对的来源清单、采集方法、版权与许可说明","frontmatter":{"title":"来源说明","description":"逐条可核对的来源清单、采集方法、版权与许可说明"},"headers":[],"relativePath":"sources.md","filePath":"sources.md","lastUpdated":null}'),i={name:"sources.md"};function h(g,t,u,p,_,b){const d=r("SourceLedger");return s(),l("div",null,[t[0]||(t[0]=e("h1",{id:"来源说明",tabindex:"-1"},[o("来源说明 "),e("a",{class:"header-anchor",href:"#来源说明","aria-label":'Permalink to "来源说明"'},"​")],-1)),t[1]||(t[1]=e("p",null,[o("本页是"),e("strong",null,"可核对清单"),o("的站点视图。所有字段来自真实 HTTP 访问日志与输入报告原文，未取得的条目不补全、不推测。")],-1)),c(d),t[2]||(t[2]=n('<h2 id="三种可核对格式" tabindex="-1">三种可核对格式 <a class="header-anchor" href="#三种可核对格式" aria-label="Permalink to &quot;三种可核对格式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>用途</th></tr></thead><tbody><tr><td><code>SOURCES.md</code></td><td>按下载状态分组的完整 Markdown 表，212 条逐条列示，便于人工阅读与版本比对</td></tr><tr><td><code>data/sources_verified.csv</code></td><td>同清单 CSV（UTF-8 BOM），含 SHA256、报告行号、报告引用语境、关联功法 ID，便于 Excel 筛选</td></tr><tr><td><code>data/visit_log.json</code></td><td>机器可读的完整访问日志：两次访问尝试、HTTP 状态、Content-Type、字节数、耗时、最终 URL、页面标题、排除原因</td></tr><tr><td><code>ASSETS.md</code> / <code>data/assets.json</code> / <code>data/assets_verified.csv</code></td><td>静态资源台账：图片、音视频、文档、样式表的下载地址、SHA256、去重关系、来源页、站内路径与受限状态，见<a href="/hello-world/gongfa-archive/media">资源库</a></td></tr></tbody></table><p>首轮探测日志另存为 <code>data/visit_log_first_pass.json</code> 与 <code>data/catalog_first_pass.json</code>，可与最终日志对照，查看哪些链接在改用 curl 与 HTTPS 升级后恢复访问。</p><h2 id="采集方法与限制" tabindex="-1">采集方法与限制 <a class="header-anchor" href="#采集方法与限制" aria-label="Permalink to &quot;采集方法与限制&quot;">​</a></h2><ol><li><strong>抽取</strong>：<code>tools/extract_sources.py</code> 从报告正文正则提取内联链接与裸 URL，保留锚文本、报告行号与该行的引用语境。</li><li><strong>首轮探测</strong>：<code>tools/collect.py</code> 用 urllib 逐条 GET，记录基线状态。</li><li><strong>最终采集</strong>：<code>tools/collect_final.py</code> 改用 curl，<code>http://</code> 失败时自动尝试 <code>https://</code> 升级；PDF 使用更长超时完整下载并校验 <code>%PDF</code> 头与 <code>%%EOF</code> 尾。</li><li><strong>落盘判定</strong>：仅政务公开网页、国家级公共平台、官方媒体公开新闻页与完整 PDF 保存；其余逐条写明原因。</li><li><strong>编译</strong>：<code>tools/build_catalog.py</code> 关联功法、生成站点数据、功法详情页与上述清单。</li></ol><p><strong>环境限制如实记录</strong>：本环境对部分 <code>http://</code>（80 端口）请求存在拦截，且第三方站点普遍设有反爬策略。最终仍有若干条目返回 HTTP 403；这些条目在清单中统一标注为「服务端拒绝访问」，<strong>未被伪装成「资料不存在」</strong>。少量链接为 404（已失效）或 502（网关错误），同样逐条注明。</p><h2 id="版权与许可" tabindex="-1">版权与许可 <a class="header-anchor" href="#版权与许可" aria-label="Permalink to &quot;版权与许可&quot;">​</a></h2><ul><li>所有第三方内容的<strong>著作权与许可归原权利人</strong>。本站不主张任何权利，也不改写原文。</li><li>已保存的<strong>网页全文与许可未明示的 PDF</strong> 仅作本地核验存档，站点不提供全文、不提供下载、不对外再发布。</li><li>在允许访问和下载的范围内，官方/政务公开页面引用的图片、公开音视频与样式表已下载到 <code>docs/public/media/</code>，在<a href="/hello-world/gongfa-archive/media">资源库</a>逐条标注原始出处、来源页、SHA256 与版权状态后展示；详见 <code>ASSETS.md</code> 与 <code>data/assets.json</code>。站点装饰图形（图标、图表、时间轴）仍为本项目原创 SVG / CSS。</li><li>音视频平台内容依其服务条款与著作权限制<strong>一律未下载</strong>，仅保留原始链接供用户自行访问。</li><li>本站不新增疗效承诺，不提供功法教学或医疗建议；详见<a href="/hello-world/gongfa-archive/about">关于与免责</a>。</li></ul><h2 id="可信度分级依据" tabindex="-1">可信度分级依据 <a class="header-anchor" href="#可信度分级依据" aria-label="Permalink to &quot;可信度分级依据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>来源类型</th><th>使用建议</th></tr></thead><tbody><tr><td>A</td><td>政府网站、国家级公共平台、国家级官方媒体</td><td>可作制度性事实依据，仍建议核对原始公告</td></tr><tr><td>B</td><td>高校、学术数据库题录、全国性专业机构官网</td><td>可作文献线索；全文通常仍需机构授权</td></tr><tr><td>C</td><td>百科词条、主流媒体报道</td><td>需与原始文献或官方名录交叉核验</td></tr><tr><td>D</td><td>自媒体、短视频、电商、个人站点</td><td>可靠性有限，仅作线索，不作事实依据</td></tr></tbody></table><blockquote><p>分级针对<strong>来源类型</strong>，不针对功法内容真伪，不构成对任何流派、机构或传承人的背书。报告本身也提示：警惕自封「大师」「嫡传」的商业包装与夸大宣传。</p></blockquote>',11))])}const m=a(i,[["render",h]]);export{S as __pageData,m as default};
